assert len({d["handle"].lower() for d in LEADS}) == len(LEADS) == 100, len(LEADS)

FOLLOWERS = "Not verified (Instagram blocks unauthenticated scraping)"
RECENT = "Not verified (public search snippets only; confirm last post date manually)"
ENGAGEMENT = "Not verified (public search snippets only)"


def block(i: int, d: dict[str, str]) -> str:
    h = d["handle"]
    lines = [
        "=" * 50,
        f"LEAD #{i}",
        "=" * 50,
        "Business Name:",
        d["business_name"],
        "Instagram Handle:",
        f"@{h}",
        "Instagram URL:",
        f"https://www.instagram.com/{h}/",
        "Followers Count:",
        FOLLOWERS,
        "City:",
        d["city"],
        "State:",
        d["state"],
        "Business Type:",
        d["business_type"],
        "WhatsApp Number:",
        d["whatsapp"],
        "Email:",
        d["email"],
        "Ordering Method:",
        d["ordering"],
        "Website Present:",
        d["website_yn"],
        "Website URL:",
        d["website_url"],
        "Recent Activity Date:",
        RECENT,
        "Average Engagement:",
        ENGAGEMENT,
        "Bio Text:",
        d["bio"],
        "Keywords:",
        d["keywords"],
        "Reason Qualified:",
        d["reason"],
        "Potential Services Needed:",
        d["services"],
        "Google Maps Link:",
        d["maps"],
        "Lead Quality Score:",
        d["score"],
        "Notes:",
        d["notes"],
        "",
    ]
    return "\n".join(lines)


header = "\n".join(
    [
        "India Jewellery Instagram / WhatsApp Lead Export",
        "Generated: 2026-05-23",
        "Maintained on branch: cursor/indian-jewellery-leads-35ab",
        "Source: Public web search snippets (Instagram posts/reels indexed by search engines).",
        "Deduping: Unique Instagram handles; consolidate duplicate WhatsApp networks at outreach time.",
        "Disclaimer: Follower counts, engagement, and last-post dates are not live-scraped from Instagram.",
        "",
    ]
)

OUT.write_text(header + "\n".join(block(i + 1, d) for i, d in enumerate(LEADS)), encoding="utf-8")
print(f"Wrote {len(LEADS)} leads to {OUT}")
